// Insert inserts the record into the database
func (t *GenJournalTemplate) Insert(runTrigger bool) bool {
	// OnInsert trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnInsert(); err != nil {
			fmt.Printf("Error: OnInsert trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, GenJournalTemplateTableName)

	// Collect arguments for INSERT
	args := []interface{}{
		t.Name,
		t.Description,
		t.Test_report_id,
		t.Page_id,
		t.Posting_report_id,
		t.Force_posting_report,
		t.Type,
		t.Source_code,
		t.Reason_code,
		t.Recurring,
		t.Force_doc_balance,
		t.Bal_account_type,
		t.Bal_account_no,
		t.No_series,
		t.Posting_no_series,
	}

	// Build SQL with placeholders. A taken key inserts nothing (ON CONFLICT … DO NOTHING) instead
	// of failing: on PostgreSQL a failed INSERT would abort the transaction
	sqlStr := fmt.Sprintf(`INSERT INTO "%s" (name, description, test_report_id, page_id, posting_report_id, force_posting_report, type, source_code, reason_code, recurring, force_doc_balance, bal_account_type, bal_account_no, no_series, posting_no_series) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT (name) DO NOTHING`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	result, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to insert Gen_Journal_Template: %v\n", err)
		return false
	}
	// The key is taken (INSERT fails in the classic way: "<Table> <key> already exists")
	if n, err := result.RowsAffected(); err == nil && n == 0 {
		_, key := t.recordKey()
		t.triggerErr = apperrors.TableRecordExists(GenJournalTemplateTableName, key)
		return false
	}
	// The record as written: its xRec from now on (a following Modify or Rename compares with it)
	t.StoreOldValues()
	return true
}

// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *GenJournalTemplate) InsertAll(records []*GenJournalTemplate, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, []interface{}{
			r.Name,
			r.Description,
			r.Test_report_id,
			r.Page_id,
			r.Posting_report_id,
			r.Force_posting_report,
			r.Type,
			r.Source_code,
			r.Reason_code,
			r.Recurring,
			r.Force_doc_balance,
			r.Bal_account_type,
			r.Bal_account_no,
			r.No_series,
			r.Posting_no_series,
		})
	}
	tableName := fmt.Sprintf("%s$%s", t.company, GenJournalTemplateTableName)
	columns := []string{"name", "description", "test_report_id", "page_id", "posting_report_id", "force_posting_report", "type", "source_code", "reason_code", "recurring", "force_doc_balance", "bal_account_type", "bal_account_no", "no_series", "posting_no_series"}
	return tables.InsertRows(t.exec(), t.dbType, tableName, columns, rows)
}

// Modify updates the record in the database
func (t *GenJournalTemplate) Modify(runTrigger bool) bool {
	// OnModify trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnModify(); err != nil {
			fmt.Printf("Error: OnModify trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// A changed primary key is a rename: run the OnRename trigger
	// before it is written; xRec values are available through OldValue
	keyChanged := false
	if t.oldValues != nil {
		if t.hasFieldChanged("name") {
			keyChanged = true
		}
	}
	if runTrigger && keyChanged {
		if err := t.runOnRename(); err != nil {
			fmt.Printf("Error: OnRename trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, GenJournalTemplateTableName)

	// Build dynamic SQL based on field tracking
	var setClauses []string
	var values []interface{}

	// If we have old values (loaded from Get), only update changed fields.
	// Changed primary key fields are renamed in place (Rename): they are SET to the
	// new value while the WHERE clause matches the old one.
	if t.oldValues != nil {
		if t.hasFieldChanged("name") {
			setClauses = append(setClauses, "name = ?")
			values = append(values, t.Name)
		}
		if t.hasFieldChanged("description") {
			setClauses = append(setClauses, "description = ?")
			values = append(values, t.Description)
		}
		if t.hasFieldChanged("test_report_id") {
			setClauses = append(setClauses, "test_report_id = ?")
			values = append(values, t.Test_report_id)
		}
		if t.hasFieldChanged("page_id") {
			setClauses = append(setClauses, "page_id = ?")
			values = append(values, t.Page_id)
		}
		if t.hasFieldChanged("posting_report_id") {
			setClauses = append(setClauses, "posting_report_id = ?")
			values = append(values, t.Posting_report_id)
		}
		if t.hasFieldChanged("force_posting_report") {
			setClauses = append(setClauses, "force_posting_report = ?")
			values = append(values, t.Force_posting_report)
		}
		if t.hasFieldChanged("type") {
			setClauses = append(setClauses, "type = ?")
			values = append(values, t.Type)
		}
		if t.hasFieldChanged("source_code") {
			setClauses = append(setClauses, "source_code = ?")
			values = append(values, t.Source_code)
		}
		if t.hasFieldChanged("reason_code") {
			setClauses = append(setClauses, "reason_code = ?")
			values = append(values, t.Reason_code)
		}
		if t.hasFieldChanged("recurring") {
			setClauses = append(setClauses, "recurring = ?")
			values = append(values, t.Recurring)
		}
		if t.hasFieldChanged("force_doc_balance") {
			setClauses = append(setClauses, "force_doc_balance = ?")
			values = append(values, t.Force_doc_balance)
		}
		if t.hasFieldChanged("bal_account_type") {
			setClauses = append(setClauses, "bal_account_type = ?")
			values = append(values, t.Bal_account_type)
		}
		if t.hasFieldChanged("bal_account_no") {
			setClauses = append(setClauses, "bal_account_no = ?")
			values = append(values, t.Bal_account_no)
		}
		if t.hasFieldChanged("no_series") {
			setClauses = append(setClauses, "no_series = ?")
			values = append(values, t.No_series)
		}
		if t.hasFieldChanged("posting_no_series") {
			setClauses = append(setClauses, "posting_no_series = ?")
			values = append(values, t.Posting_no_series)
		}

		// If nothing changed, skip update
		if len(setClauses) == 0 {
			return true // No changes, success
		}
	} else {
		// No old values (fresh record), update all fields
		setClauses = append(setClauses, "description = ?")
		values = append(values, t.Description)
		setClauses = append(setClauses, "test_report_id = ?")
		values = append(values, t.Test_report_id)
		setClauses = append(setClauses, "page_id = ?")
		values = append(values, t.Page_id)
		setClauses = append(setClauses, "posting_report_id = ?")
		values = append(values, t.Posting_report_id)
		setClauses = append(setClauses, "force_posting_report = ?")
		values = append(values, t.Force_posting_report)
		setClauses = append(setClauses, "type = ?")
		values = append(values, t.Type)
		setClauses = append(setClauses, "source_code = ?")
		values = append(values, t.Source_code)
		setClauses = append(setClauses, "reason_code = ?")
		values = append(values, t.Reason_code)
		setClauses = append(setClauses, "recurring = ?")
		values = append(values, t.Recurring)
		setClauses = append(setClauses, "force_doc_balance = ?")
		values = append(values, t.Force_doc_balance)
		setClauses = append(setClauses, "bal_account_type = ?")
		values = append(values, t.Bal_account_type)
		setClauses = append(setClauses, "bal_account_no = ?")
		values = append(values, t.Bal_account_no)
		setClauses = append(setClauses, "no_series = ?")
		values = append(values, t.No_series)
		setClauses = append(setClauses, "posting_no_series = ?")
		values = append(values, t.Posting_no_series)
	}

	// Add WHERE clause value (primary key as loaded, so a renamed key still matches)
	if old, ok := t.oldValues["name"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Name)
	}
	// Renamed key fields that other tables refer to (Rename): carried over below
	type renamedKey struct {
		field    string
		old, new interface{}
	}
	var renamed []renamedKey
	if t.oldValues != nil {
		if t.hasFieldChanged("name") {
			renamed = append(renamed, renamedKey{"name", t.oldValues["name"], t.Name})
		}
	}

	// Build and execute SQL
	sqlStr := fmt.Sprintf(`UPDATE "%s" SET %s WHERE 1=1 AND name = ?`,
		tableName,
		strings.Join(setClauses, ", "),
	)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(values))

	_, err := t.exec().Exec(sqlStr, values...)
	if err != nil {
		fmt.Printf("Error: Failed to modify Gen_Journal_Template: %v\n", err)
		return false
	}
	// A temporary record's rename stays in the record: other tables are not changed
	for _, r := range renamed {
		if t.temp != nil {
			break
		}
		if err := t.renameReferences(r.field, r.old, r.new); err != nil {
			fmt.Printf("Error: Failed to rename references to Gen_Journal_Template: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// The stored record now matches the current values (including a renamed key)
	if t.oldValues != nil {
		t.StoreOldValues()
	}
	return true
}

